def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider and compare the equally sized panels on either side.
    for c in range(1, w - 1):
        if all(row[c] == grid[0][c] for row in grid):
            width = min(c, w - c - 1)
            left_start = c - width
            right_start = c + 1
            return [
                [3 if grid[r][left_start + j] == grid[r][right_start + j] else 4
                 for j in range(width)]
                for r in range(h)
            ]

    for r in range(1, h - 1):
        if all(value == grid[r][0] for value in grid[r]):
            height = min(r, h - r - 1)
            top_start = r - height
            bottom_start = r + 1
            return [
                [3 if grid[top_start + i][c] == grid[bottom_start + i][c] else 4
                 for c in range(w)]
                for i in range(height)
            ]

    return []
